def page(key,title,subtitle,body,script='',actions='',eyebrow='Research workspace'):
 nav=''.join(f'<a class="{"active" if k==key else ""}" href="{k}.html">{t}</a>' for k,t in pages)
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title} · Agentic Arena</title><style>{css}</style></head><body><main class="shell"><header class="top"><a class="brand" href="index.html"><span class="logo">△</span> AGENTIC ARENA</a><nav class="nav">{nav}</nav><span class="demo">DEMO / 042</span></header><section class="heading"><div><div class="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{subtitle}</p></div><div class="actions">{actions}</div></section>{body}<footer class="footer"><span>AGENTIC ARENA / Research interface prototype</span><span>Illustrative data · Not measured benchmark results</span></footer></main><script>{script}</script></body></html>'''
 (p/(key+'.html')).write_text(html)

def metric(name,value,color='cyan',id=''):
 return f'<div class="metric"><div><small>{name}</small><strong {("id="+chr(34)+id+chr(34)) if id else ""}>{value}</strong></div><svg class="spark" viewBox="0 0 72 30" aria-hidden="true"><path d="M1 25 L10 19 L19 22 L29 11 L39 15 L49 8 L59 12 L71 3" fill="none" stroke="var(--{color})" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg></div>'
def metrics(items):return f'<div class="metrics" style="--n:{len(items)}">'+''.join(metric(*x) for x in items)+'</div>'
def panel(title,content,extra='',cls=''):return f'<section class="panel {cls}"><div class="panel-head"><h2>{title}</h2>{extra}</div>{content}</section>'
def svg_start(w,h):return f'<svg viewBox="0 0 {w} {h}" role="img" aria-label="Agent graph"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10 z" fill="#7598ad"/></marker></defs>'
def node(x,y,w,title,sub,icon='◇',status='',idx=''):
 return f'<g class="node {status}" tabindex="0" role="button" aria-label="Inspect {title}" data-node="{idx or title}"><rect x="{x}" y="{y}" width="{w}" height="60" rx="8"/><text class="node-icon" x="{x+14}" y="{y+34}">{icon}</text><text class="node-title" x="{x+35}" y="{y+25}">{title}</text><text class="node-sub" x="{x+35}" y="{y+42}">{sub}</text></g>'
def edge(d,c=''):return f'<path class="edge {c}" d="{d}"/>'
def kv(k,v):return f'<div class="kv"><span>{k}</span><strong>{v}</strong></div>'
def status(v):return f'<span class="status {v.lower()}">{v}</span>'
def table(headers,rows,cl=''):return f'<div class="tablewrap"><table class="{cl}"><thead><tr>'+''.join(f'<th>{x}</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{x}</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def legend(items):return '<div class="legend">'+''.join(f'<span><i class="swatch" style="background:var(--{c})"></i>{t}</span>' for c,t in items)+'</div>'
