script='''const info={"User task":["Receive task input.","Done","145","0.18 s","None"],Planner:["Create a task-specific plan.","Done","1,326","0.91 s","None"],Researcher:["Gather evidence using external tools.","Running","4,218","2.14 s","Search, Read"],Analyzer:["Analyze gathered information.","Queued","—","—","Calculator"],Validator:["Check the output against acceptance criteria.","Queued","—","—","None"],"Final output":["Package the validated result.","Queued","—","—","None"]};function select(n){document.querySelectorAll('.node').forEach(x=>x.classList.toggle('selected',x===n));let k=n.dataset.node,v=info[k];document.querySelector('#inspector').innerHTML=`<div class="eyebrow">Selected node</div><div class="inspector-title">${k}</div><p class="description">${v[0]}</p>`+[['Status',v[1]],['Model','Shared LLM'],['Tokens',v[2]],['Elapsed',v[3]],['Tools',v[4]]].map(x=>`<div class="kv"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}document.querySelectorAll('.node').forEach(n=>{n.onclick=()=>select(n);n.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(n)}}});let paused=false;document.querySelector('#pause').onclick=e=>{paused=!paused;document.querySelector('#canvas').classList.toggle('paused',paused);e.target.textContent=paused?'Resume':'Pause';document.querySelector('#runstatus').textContent=paused?'Paused':'Running'};'''
