script=f'''let runs={json.dumps(runs)},sel=1,paused=false,elapsed=42.8;const $=s=>document.querySelector(s);function render(){{$('#fwlist').innerHTML=runs.map((a,i)=>`<button class="fw ${{i===sel?'selected':''}}" data-i="${{i}}"><b>${{a[0]}}</b><span class="status ${{a[1]===100?'done':'running'}}">${{a[1]===100?'Done':'Running'}}</span><small>${{a[3].toLocaleString()}} tokens</small><small>${{a[1]}}%</small><div class="bar"><i style="width:${{a[1]}}%;background:var(--${{a[1]===100?'green':'cyan'}})"></i></div></button>`).join('');document.querySelectorAll('.fw').forEach(b=>b.onclick=()=>{{sel=+b.dataset.i;render()}});let a=runs[sel];$('#selectedName').textContent=a[0];$('#selectedProgress').textContent=a[1]+'%';$('#selectedBar').style.width=a[1]+'%';$('#selectedTokens').textContent=a[3].toLocaleString();$('#selectedStatus').textContent=a[1]===100?'Done':'Running';$('#selectedStatus').className='status '+(a[1]===100?'done':'running');document.querySelectorAll('.canvas .node').forEach((n,i)=>{{n.classList.toggle('complete',a[1]===100||i===0);n.classList.toggle('running',a[1]<100&&i===1)}});$('#completed').textContent=runs.filter(x=>x[1]===100).length+' / 10';$('#total').textContent=(runs.reduce((s,x)=>s+x[3],0)/1000).toFixed(1)+'K';$('#elapsed').textContent=elapsed.toFixed(1)+' s'}}function event(name,detail){{const e=document.createElement('div');e.className='event';e.innerHTML=`<i class="dot"></i><div><b>${{name}}</b><div class="detail">${{detail}}</div></div><span class="time">${{new Date().toLocaleTimeString('en-GB')}}</span>`;$('#events').prepend(e);while($('#events').children.length>7)$('#events').lastChild.remove()}};'''.replace("en-GB'))","en-GB')}")
# avoid formatting pitfalls in generated JS
script=script[:script.index('function event')]+'''function event(name,detail){const e=document.createElement('div');e.className='event';e.innerHTML='<i class="dot"></i><div><b>'+name+'</b><div class="detail">'+detail+'</div></div><span class="time">'+new Date().toLocaleTimeString('en-GB')+'</span>';$('#events').prepend(e);while($('#events').children.length>7)$('#events').lastChild.remove()}event('LangGraph','Validation completed');event('Google ADK','Tool invocation started');event('CrewAI','Research agent active');event('Agno','Run completed');render();let timer=setInterval(()=>{if(paused)return;let pending=runs.filter(a=>a[1]<100);if(!pending.length)return;let a=pending[Math.floor(Math.random()*pending.length)];a[1]=Math.min(100,a[1]+Math.ceil(Math.random()*5));a[3]+=100;elapsed+=1.5;event(a[0],a[1]===100?'Run completed':'Agent step completed');render()},1500);$('#pause').onclick=e=>{paused=!paused;e.target.textContent=paused?'Resume demo':'Pause demo';$('#stream').textContent=paused?'Paused':'Demo stream';document.querySelector('.canvas').classList.toggle('paused',paused)};'''
