script='''const links=LINKS;const target=document.querySelector('#agentinfo'),initial=target.innerHTML;function inspect(n){document.querySelectorAll('.node').forEach(x=>x.classList.toggle('selected',x===n));let a=n.dataset.node,send=links.filter(x=>x[0]===a),recv=links.filter(x=>x[1]===a),sum=(arr,i)=>arr.reduce((s,x)=>s+x[i],0);target.innerHTML='<div class="eyebrow">Selected agent</div><div class="inspector-title">'+a+'</div>'+[['Sent messages',sum(send,2)],['Received messages',sum(recv,2)],['Outgoing tokens',sum(send,3)],['Incoming tokens',sum(recv,3)],['Outgoing handoffs',sum(send,4)]].map(x=>'<div class="kv"><span>'+x[0]+'</span><strong>'+x[1].toLocaleString()+'</strong></div>').join('')}document.querySelectorAll('.node').forEach(n=>{n.onclick=()=>inspect(n);n.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();inspect(n)}}});document.querySelector('#reset').onclick=()=>{target.innerHTML=initial;document.querySelectorAll('.node').forEach(x=>x.classList.remove('selected'))};'''.replace('LINKS',json.dumps(links))
