script='''const names=NAMES,caps=CAPS,mat=MAT;const $=s=>document.querySelector(s),states=[['unknown','?','Unverified'],['adapter','~','Adapter'],['native','✓','Native']];function render(){let q=$('#search').value.toLowerCase(),f=$('#filter').value;$('#matrix').innerHTML=names.map((n,i)=>!n.toLowerCase().includes(q)?'':'<tr><td><b>'+n+'</b></td>'+mat[i].map((v,j)=>{let a=states[v];return '<td><button class="cell '+a[0]+(f!=='all'&&+f!==v?' hidden':'')+'" data-i="'+i+'" data-j="'+j+'" title="'+n+' / '+caps[j]+': '+a[2]+'" aria-label="'+n+' / '+caps[j]+': '+a[2]+'">'+a[1]+'</button></td>'}).join('')+'</tr>').join('')||'<tr><td colspan="11" class="empty">No matching frameworks</td></tr>';document.querySelectorAll('.cell').forEach(b=>b.onclick=()=>{let i=+b.dataset.i,j=+b.dataset.j;$('#detail').innerHTML='<div class="eyebrow">Demo classification</div><b>'+names[i]+' / '+caps[j]+'</b><p class="description">'+states[mat[i][j]][2]+' · Illustrative only. Confirm with official documentation and reproducible tests before using as evidence.</p>'})}$('#search').oninput=render;$('#filter').onchange=render;render();'''.replace('NAMES',json.dumps(frameworks)).replace('CAPS',json.dumps(caps)).replace('MAT',json.dumps(mat))
