script='''const names=NAMES,values=VALUES,$=s=>document.querySelector(s),defaults=[40,25,20,15];let weights=defaults.slice();function render(){weights=defaults.map((_,i)=>+$('#w'+i).value);let total=weights.reduce((a,b)=>a+b,0),min=+$('#threshold').value;weights.forEach((w,i)=>$('#v'+i).textContent=(total?(w/total*100).toFixed(0):0)+'%');$('#minv').textContent=min;let pool=names.map((name,i)=>({name,v:values[i]})).filter(a=>a.v[0]>=min),rank=total?pool.map(a=>({...a,score:a.v.reduce((s,v,i)=>s+v*weights[i],0)/total})).sort((a,b)=>b.score-a.score):[];$('#eligible').textContent=pool.length;$('#topscore').textContent=rank.length?rank[0].score.toFixed(1):'—';let top=rank[0];$('#recommend').innerHTML=top?'<div class="eyebrow">Top weighted match</div><div class="inspector-title">'+top.name+'</div><div class="score">'+top.score.toFixed(1)+'<span style="font-size:15px;color:var(--muted)"> / 100</span></div><p class="description">Highest weighted demo score among eligible candidates.</p>'+['Quality','Speed','Token efficiency','Reliability'].map((n,i)=>'<div class="kv"><span>'+n+'</span><strong>'+top.v[i]+'/100</strong></div>').join(''):'<p class="description">'+(total?'No framework meets the quality threshold.':'Set at least one nonzero weight.')+'</p>';$('#ranks').innerHTML=rank.map((a,i)=>'<tr class="rankrow '+(i===0?'highlight':'')+'"><td>'+ (i+1)+'</td><td><b>'+a.name+'</b></td><td><strong>'+a.score.toFixed(1)+'</strong></td>'+a.v.map(v=>'<td>'+v+'<div class="bar" style="margin-top:4px"><i style="width:'+v+'%"></i></div></td>').join('')+'</tr>').join('')||'<tr><td colspan="7" class="empty">No ranked candidates</td></tr>';let x=v=>48+(v-60)*8.1,y=v=>220-(v-70)*6.2;let svg='';for(let v=60;v<=100;v+=10)svg+='<line x1="'+x(v)+'" y1="34" x2="'+x(v)+'" y2="220" stroke="#263241"/><text x="'+x(v)+'" y="237" text-anchor="middle" fill="#91a0b4" font-size="10">'+v+'</text>';for(let v=70;v<=100;v+=10)svg+='<line x1="48" y1="'+y(v)+'" x2="372" y2="'+y(v)+'" stroke="#263241"/><text x="38" y="'+(y(v)+3)+'" text-anchor="end" fill="#91a0b4" font-size="10">'+v+'</text>';svg+='<text x="210" y="259" text-anchor="middle" fill="#91a0b4" font-size="11">Speed score →</text><text x="10" y="20" fill="#91a0b4" font-size="11">Quality ↑</text>';let pareto=pool.filter(a=>!pool.some(b=>b.v[0]>=a.v[0]&&b.v[1]>=a.v[1]&&(b.v[0]>a.v[0]||b.v[1]>a.v[1]))).sort((a,b)=>a.v[1]-b.v[1]);if(pareto.length>1)svg+='<polyline points="'+pareto.map(a=>x(a.v[1])+','+y(a.v[0])).join(' ')+'" stroke="#ae92f5" stroke-width="1.5" stroke-dasharray="5 4" fill="none"/>';names.forEach((n,i)=>{let v=values[i],active=top&&n===top.name;svg+='<circle cx="'+x(v[1])+'" cy="'+y(v[0])+'" r="'+(active?6:4)+'" fill="'+(active?'#53cbe8':v[0]>=min?'#719dff':'#49576b')+'"><title>'+n+' · Quality '+v[0]+' · Speed '+v[1]+'</title></circle>';if(active)svg+='<text x="'+x(v[1])+'" y="'+(y(v[0])-12)+'" text-anchor="middle" fill="#53cbe8" font-size="11">'+n+'</text>'});$('#scatter').innerHTML=svg}defaults.forEach((_,i)=>$('#w'+i).oninput=render);$('#threshold').oninput=render;$('#reset').onclick=()=>{defaults.forEach((v,i)=>$('#w'+i).value=v);$('#threshold').value=80;render()};render();'''.replace('NAMES',json.dumps(frameworks)).replace('VALUES',json.dumps(scores))
